#!/bin/bash
# ⚡ 离线秒级中文语言包注入脚本 (兼容 Debian/Ubuntu/Armbian/Alpine)
[ "$EUID" -ne 0 ] && echo "错误：请以 root 权限运行" && exit 1

echo "⚡ 正在注入中文语言环境与编辑器语言包..."

# 1. 创建基础语言目录
mkdir -p /usr/share/locale/zh_CN/LC_MESSAGES/
mkdir -p /usr/share/locale/zh_CN.UTF-8/LC_MESSAGES/

# 2. 释放 Nano 语言包 (适配 glibc 与 Alpine musl)
NANO_DATA=""
if [ -n "$NANO_DATA" ]; then
    echo "$NANO_DATA" | base64 -d > /usr/share/locale/zh_CN/LC_MESSAGES/nano.mo
    cp /usr/share/locale/zh_CN/LC_MESSAGES/nano.mo /usr/share/locale/zh_CN.UTF-8/LC_MESSAGES/nano.mo 2>/dev/null
fi

# 3. 释放 Vim 语言包 (自动适配各类系统的 Vim runtime 路径)
VIM_DATA=""
if [ -n "$VIM_DATA" ]; then
    VIM_DIRS=$(ls -d /usr/share/vim/vim* 2>/dev/null)
    if [ -n "$VIM_DIRS" ]; then
        for vdir in $VIM_DIRS; do
            mkdir -p "$vdir/lang/zh_CN.UTF-8/LC_MESSAGES/"
            mkdir -p "$vdir/lang/zh_CN/LC_MESSAGES/"
            echo "$VIM_DATA" | base64 -d > "$vdir/lang/zh_CN.UTF-8/LC_MESSAGES/vim.mo"
            echo "$VIM_DATA" | base64 -d > "$vdir/lang/zh_CN/LC_MESSAGES/vim.mo"
        done
    fi
    echo "$VIM_DATA" | base64 -d > /usr/share/locale/zh_CN/LC_MESSAGES/vim.mo
fi

# 4. 全局环境变量配置
cat << 'ENV' > /etc/profile.d/zh_CN.sh
export LANG=zh_CN.UTF-8
export LANGUAGE=zh_CN:zh
export LC_ALL=zh_CN.UTF-8
ENV

# 5. Alpine 系统的额外兼容性写入
if [ -f /etc/alpine-release ]; then
    cat << 'ENV' >> /etc/environment
LANG=zh_CN.UTF-8
LANGUAGE=zh_CN:zh
LC_ALL=zh_CN.UTF-8
ENV
fi

chmod +x /etc/profile.d/zh_CN.sh

# 6. 刷新当前 Shell 会话
export LANG=zh_CN.UTF-8
export LANGUAGE=zh_CN:zh
export LC_ALL=zh_CN.UTF-8

echo "------------------------------------------------------------"
echo -e "\033[1;32m✅ 极速配置完成！(耗时 < 0.1s)\033[0m"
echo -e "\033[1;33m📢 请重新连接终端或重新打开 Vim/Nano 测试\033[0m"
echo "------------------------------------------------------------"
